    "statement": "Plausible if scaling changed or load shifted onto fewer replicas of service:gridcast:forecast-pipeline."
  },
  {
    "root_cause": "Increased per-request work due to data or configuration change",
    "mechanism": "A change in forecast grid size, ensemble size, or input data volume increased computation per request enough to push p95 duration above 5s.",
    "statement": "Plausible if a recent deployment or input data expansion affected service:gridcast:forecast-pipeline."
  },
  {
    "root_cause": "Cache failure or mass cache invalidation",
    "mechanism": "A caching layer serving the forecast pipeline failed or was invalidated, forcing expensive recomputation or repeated data fetches.",
    "statement": "Plausible for a sudden onset and recovery if the cache was repopulated."
  },
  {
    "root_cause": "Network degradation between forecast-pipeline and dependencies",
    "mechanism": "Packet loss or increased network latency caused slow I/O, retries, or timeouts on calls to downstream data stores or APIs.",
    "statement": "Less likely if only service:gridcast:forecast-pipeline showed symptoms, but still possible."
  }
]}
